#!/bin/sh
# Generated by ws setup. Serialize Windows disk ownership with the mount helper.
[ "$1" = '@DOMAIN@' ] || exit 0
case "$2/$3" in prepare/begin|release/end) ;; *) exit 0 ;; esac
state='/run/window-side-ntfs-@UUID@'
mkdir -p -m 700 "$state" || exit 1
exec 9>"$state/lock"
flock -w 40 9 || exit 1
part=$(readlink -f /dev/disk/by-uuid/@UUID@) && [ -b "$part" ] || exit 1
if [ "$2" = prepare ]; then
    if findmnt -rn -S "$part" >/dev/null; then
        echo 'Windows drive is mounted on Linux; close files and unmount it first.' >&2
        exit 1
    fi
    touch "$state/busy"
    exit $?
fi
rm -f "$state/busy"
for tool in ntfsfix ntfsinfo ntfsls; do command -v "$tool" >/dev/null 2>&1 || exit 0; done
findmnt -rn -S "$part" >/dev/null && exit 0
listing=$(ntfsls -f "$part" 2>/dev/null) || exit 0
printf '%s\n' "$listing" | grep -qix hiberfil.sys && exit 0
ntfsinfo -f -m "$part" 2>/dev/null | grep -q 'Volume Flags:.*DIRTY' || exit 0
if timeout 30 ntfsfix -d "$part"; then
    logger -t window-side "Cleared the Windows dirty flag on $part"
else
    logger -t window-side "Windows dirty flag cleanup failed on $part; repair required"
fi
exit 0
